// ***************
// Filename: intc_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of intc: joins the register map intc_regs
//   (modport regs) and the logic intc (modport core). cfg_* go from the
//   register map to the logic (register values, _wr write pulses, _rd read
//   pulses), sts_* come back (values read, _set / _clr hardware set / clear
//   pulses). A logic block ties every sts_* member it does not use to 0.
//   Generated by ip/scripts/regmap_gen.py from intc_regs.json: edit the JSON
//   and regenerate.
// Date: 2026-10-20
interface intc_regs_if #(
  parameter int NUM_IRQ = 16
) ();
  logic [NUM_IRQ-1:0] cfg_enable;
  logic cfg_enable_wr;
  logic [NUM_IRQ-1:0] cfg_edge_type;
  logic cfg_edge_type_wr;
  logic [NUM_IRQ-1:0] cfg_active_low;
  logic cfg_active_low_wr;
  logic [NUM_IRQ-1:0] sts_pending;
  logic [NUM_IRQ-1:0] cfg_pending;
  logic cfg_pending_wr;
  logic [NUM_IRQ-1:0] cfg_soft_set;
  logic cfg_soft_set_wr;
  logic [32-1:0] sts_vector;
  logic [NUM_IRQ-1:0] sts_masked;

  modport regs (output cfg_enable, cfg_enable_wr, cfg_edge_type, cfg_edge_type_wr, cfg_active_low,
    cfg_active_low_wr, cfg_pending, cfg_pending_wr, cfg_soft_set, cfg_soft_set_wr, input sts_pending,
    sts_vector, sts_masked);
  modport core (output sts_pending, sts_vector, sts_masked, input cfg_enable, cfg_enable_wr, cfg_edge_type,
    cfg_edge_type_wr, cfg_active_low, cfg_active_low_wr, cfg_pending, cfg_pending_wr, cfg_soft_set,
    cfg_soft_set_wr);
  modport monitor (input cfg_enable, cfg_enable_wr, cfg_edge_type, cfg_edge_type_wr, cfg_active_low,
    cfg_active_low_wr, cfg_pending, cfg_pending_wr, cfg_soft_set, cfg_soft_set_wr, sts_pending, sts_vector,
    sts_masked);
endinterface
